"""
Perceptron-style prototype training for TabularHDC.

Only the prototype rule changes. The encoder (feature IDs, level memory, XOR binding,
majority bundling) is inherited unchanged from TabularHDCClassifier, so any difference in
results comes from training alone.

Rule, per event k:
  1. start the accumulator from the sum of the positive (event on) frames only
  2. each epoch: score every training frame, then mark mistakes
       positive frame scoring <= 0   -> add it to the accumulator
       negative frame scoring  > 0   -> subtract it from the accumulator
  3. stop early when there are no mistakes, or after max_epochs
  4. prototype = sign(accumulator), ties broken at random (seeded)

Changes against the original fit():
  - positives-only start instead of add-positive, subtract-negative
  - updates only on mistakes
  - random tie break for the prototype (original: ties become 0)
  - the encoder and predict_proba are inherited, unchanged

Not tested on GAL. Run it against TabularHDCClassifier on the same split before using it.
"""
import numpy as np
from sklearn.metrics import roc_curve,roc_auc_score

from tabular_hdc import TabularHDCClassifier   # your original class, saved as tabular_hdc.py


class TabularHDCPerceptron(TabularHDCClassifier):
    def __init__(self, D=10000, num_features=32, num_levels=21, seed=42,
                 max_epochs=5, tie_seed=0):
        super().__init__(D=D, num_features=num_features, num_levels=num_levels, seed=seed)
        self.max_epochs = max_epochs
        self.tie_rng = np.random.default_rng(tie_seed)
        self.epochs_used = None          # per event, set by fit()

    def _sign_random_tie(self, acc):
        s = np.sign(acc).astype(np.int64)
        zeros = s == 0
        s[zeros] = self.tie_rng.choice([-1, 1], size=int(zeros.sum()))
        return s

    def fit(self, X_train, y_train):
        """Overrides TabularHDCClassifier.fit. Same encoder, different prototype rule."""
        n, n_events = y_train.shape
        H = self.encode_dataset(X_train)
        B = np.where(H == 1, 1, -1).astype(np.int64)          # bipolar, for accumulation only

        self.epochs_used = np.zeros(n_events, dtype=int)
        protos = np.zeros((n_events, self.D), dtype=np.uint8)
        for k in range(n_events):
            pos = y_train[:, k] == 1
            acc = B[pos].sum(axis=0)                           # step 1: positives only
            for epoch in range(self.max_epochs):
                P = self._sign_random_tie(acc)                 # current prototype, bipolar
                scores = B @ P                                 # dot product, centred at 0
                wrong_pos = pos & (scores <= 0)                # step 2: mistakes only
                wrong_neg = (~pos) & (scores > 0)
                if not wrong_pos.any() and not wrong_neg.any():
                    break                                      # step 3: nothing left to fix
                acc += B[wrong_pos].sum(axis=0) - B[wrong_neg].sum(axis=0)
                self.epochs_used[k] = epoch + 1
            protos[k] = (self._sign_random_tie(acc) > 0).astype(np.uint8)   # step 4
        self.prototypes = protos

    def training_thresholds(self, X_train, y_train):
        """Per-event threshold on the training similarity (Youden). Use for UAR and confusion
        matrices only. AUC does not use it. Never tune on the validation or test series."""
        sims = self.predict_proba(X_train)
        thr = np.full(y_train.shape[1], 0.5)
        for k in range(y_train.shape[1]):
            y = y_train[:, k].astype(int)
            if y.sum() == 0 or y.sum() == len(y):
                continue
            fpr, tpr, th = roc_curve(y, sims[:, k])
            thr[k] = th[np.argmax(tpr - fpr)]
        return thr


